<?php
declare(strict_types=1);
require_once __DIR__ . '/../../config.php';

$pageRole = basename(__FILE__, '_inventory.php');
$roles = ['admin'=>['shop admin','admin'], 'technician'=>['technician','tech'], 'salesperson'=>['salesperson','sales']];
if (!isset($roles[$pageRole])) { http_response_code(404); exit('Inventory page not found.'); }
function inv_h($value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function inv_csrf(): string { return $_SESSION['inv_csrf'] ??= bin2hex(random_bytes(32)); }
function inv_flash(string $kind,string $message): void { $_SESSION['inv_flash']=[$kind,$message]; }
function inv_go(): void { header('Location: '.basename(__FILE__)); exit; }
function inv_role_matches(string $role,array $allowed): bool { return in_array(strtolower(trim($role)),$allowed,true); }
function inv_stock_state(int $quantity,int $minimum): array { if($quantity<=0)return ['Out of stock','out']; if($quantity<=$minimum)return ['Low stock','warn']; return ['In stock','good']; }

/* Each role file authenticates against the project's existing prism.users table. */
$action=(string)($_POST['action']??'');
if ($action==='login' && $_SERVER['REQUEST_METHOD']==='POST') {
    if (!hash_equals(inv_csrf(),(string)($_POST['csrf']??''))) { inv_flash('error','Session expired. Please try again.'); inv_go(); }
    $username=trim((string)($_POST['username']??''));
    $statement=$link->prepare("SELECT user_id,name,username,password_hash,role FROM users WHERE username=? AND user_status='Active' LIMIT 1");
    $statement->bind_param('s',$username);$statement->execute();$account=$statement->get_result()->fetch_assoc();
    if ($account && password_verify((string)($_POST['password']??''),(string)$account['password_hash']) && inv_role_matches($account['role'],$roles[$pageRole])) {
        session_regenerate_id(true);$_SESSION['inventory_user']=['id'=>(int)$account['user_id'],'name'=>$account['name'],'username'=>$account['username'],'role'=>$account['role']];inv_go();
    }
    inv_flash('error','The credentials do not match an active account for this role.');inv_go();
}
if ($action==='logout') { unset($_SESSION['inventory_user']);session_regenerate_id(true);header('Location: ../../login.php');exit; }
$user=$_SESSION['inventory_user']??null;
if ($user && !inv_role_matches((string)$user['role'],$roles[$pageRole])) { unset($_SESSION['inventory_user']);$user=null; }
if (!$user) {
    $flash=$_SESSION['inv_flash']??null;unset($_SESSION['inv_flash']);
    $roleLabel=$pageRole==='admin'?'Shop Admin':($pageRole==='technician'?'Technician':'Salesperson');
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · PRISM <?=inv_h($roleLabel)?></title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Mono:wght@700&display=swap" rel="stylesheet"><link rel="stylesheet" href="../../css/prism.css?v=inventory-modal-2"></head><body class="login-body"><main class="login-layout"><section class="login-promo"><a class="brand" href="#"><span class="mark">P</span><span>PRISM</span></a><div class="promo-copy"><span class="promo-tag">PHONE REPAIR INVENTORY MANAGEMENT</span><h1>Every part.<br><em>In focus.</em></h1><p>Sign in to the <?=inv_h(strtolower($roleLabel))?> inventory workspace.</p></div><div class="promo-bottom">INVENTORY MANAGEMENT</div></section><section class="login-panel"><div class="login-card"><span class="eyebrow"><?=inv_h(strtoupper($roleLabel))?> WORKSPACE</span><h2>Welcome back</h2><p class="muted">Use your PRISM account to continue.</p><?php if($flash):?><div class="flash <?=inv_h($flash[0])?>"><?=inv_h($flash[1])?></div><?php endif?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=inv_h(inv_csrf())?>"><input type="hidden" name="action" value="login"><label>Username<input class="input" name="username" autocomplete="username" required autofocus></label><label>Password<input class="input" type="password" name="password" autocomplete="current-password" required></label><button class="btn primary full">Sign in</button></form></div></section></main></body></html><?php exit;
}

/* Role-specific actions are handled in this page; all queries use the existing MySQL schema. */
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!hash_equals(inv_csrf(),(string)($_POST['csrf']??''))) { inv_flash('error','Invalid request token. Refresh and try again.'); inv_go(); }
    $id=(int)($_POST['id']??$_POST['part_id']??0);$quantity=max(0,(int)($_POST['quantity']??0));
    try {
        if ($pageRole==='admin') {
            if ($action==='delete') { $statement=$link->prepare('DELETE FROM parts WHERE parts_id=?');$statement->bind_param('i',$id);$statement->execute();inv_flash('success','Inventory part deleted.');inv_go(); }
            if ($action==='restock') { if($id<1||$quantity<1)throw new RuntimeException('Enter a stock quantity greater than zero.');$link->begin_transaction();$statement=$link->prepare('SELECT sku,parts_name FROM parts WHERE parts_id=? FOR UPDATE');$statement->bind_param('i',$id);$statement->execute();$part=$statement->get_result()->fetch_assoc();if(!$part)throw new RuntimeException('Inventory part was not found.');$statement=$link->prepare('UPDATE parts SET quantity=quantity+? WHERE parts_id=?');$statement->bind_param('ii',$quantity,$id);$statement->execute();$person=(string)$user['name'];$role=(string)$user['role'];$detail='Stock replenished: +'.$quantity.' × '.$part['parts_name'];$reference=(string)$part['sku'];$statement=$link->prepare('INSERT INTO activity_log(user_name,role,action,reference) VALUES(?,?,?,?)');$statement->bind_param('ssss',$person,$role,$detail,$reference);$statement->execute();$link->commit();inv_flash('success',$quantity.' units added to '.$part['parts_name'].'.');inv_go(); }
            if (!in_array($action,['create','update'],true)) throw new RuntimeException('Unsupported inventory action.');
            $sku=strtoupper(trim((string)($_POST['sku']??'')));$name=trim((string)($_POST['name']??''));$categoryChoice=trim((string)($_POST['category']??''));$categories=['Parts','Screen','Battery','Charging','Camera','Speaker','Accessory','Consumables','Tools'];$category=$categoryChoice==='Other'?trim((string)($_POST['category_other']??'')):$categoryChoice;$brand=trim((string)($_POST['brand']??''));$deviceInput=$_POST['devices']??($_POST['device']??[]);$deviceValues=is_array($deviceInput)?$deviceInput:explode(',',(string)$deviceInput);$deviceValues=array_values(array_unique(array_filter(array_map(static fn($value)=>trim((string)$value),$deviceValues),static fn($value)=>$value!=='')));$device=implode(', ',$deviceValues);$qty=max(0,(int)($_POST['quantity']??0));$minimum=max(0,(int)($_POST['minimum_stock']??0));$price=max(0,(float)($_POST['price']??0));
            if ($sku===''||$name===''||$category==='') throw new RuntimeException('SKU, part name, and category are required.');if($categoryChoice!=='Other'&&!in_array($categoryChoice,$categories,true))throw new RuntimeException('Choose a listed category or select Other.');
            if ($action==='create') {$statement=$link->prepare('INSERT INTO parts(sku,parts_name,parts_brand,parts_category,parts_compatible_device,quantity,minimum_stock,parts_price,parts_status) VALUES(?,?,?,?,?,?,?,?,\'Active\')');$statement->bind_param('sssssiid',$sku,$name,$brand,$category,$device,$qty,$minimum,$price);}
            else {$statement=$link->prepare('UPDATE parts SET sku=?,parts_name=?,parts_brand=?,parts_category=?,parts_compatible_device=?,quantity=?,minimum_stock=?,parts_price=? WHERE parts_id=?');$statement->bind_param('sssssiidi',$sku,$name,$brand,$category,$device,$qty,$minimum,$price,$id);}
            $statement->execute();inv_flash('success',$action==='create'?'Part added to inventory.':'Part updated.');inv_go();
        }
        $allowedAction=$pageRole==='technician'?'use_part':'record_sale';if($action!==$allowedAction||$id<1||$quantity<1)throw new RuntimeException('Choose a part and enter a quantity greater than zero.');
        $link->begin_transaction();$statement=$link->prepare("SELECT sku,parts_name,quantity FROM parts WHERE parts_id=? FOR UPDATE");$statement->bind_param('i',$id);$statement->execute();$part=$statement->get_result()->fetch_assoc();if(!$part||(int)$part['quantity']<$quantity)throw new RuntimeException('This part is unavailable or there is not enough stock.');
        if($pageRole==='technician'){$repairId=(int)($_POST['repair_id']??0);$userId=(int)$user['id'];$statement=$link->prepare("SELECT repair_id FROM repairs WHERE repair_id=? AND user_id=? AND LOWER(repair_status) NOT IN ('completed','collected','cancelled') FOR UPDATE");$statement->bind_param('ii',$repairId,$userId);$statement->execute();if(!$statement->get_result()->fetch_assoc())throw new RuntimeException('Select an open repair assigned to your account.');$statement=$link->prepare('INSERT INTO repair_part(repair_id,parts_id,quantity_used) VALUES(?,?,?)');$statement->bind_param('iii',$repairId,$id,$quantity);$statement->execute();$detail='Used '.$quantity.' × '.$part['parts_name'].' on repair RJ-'.str_pad((string)$repairId,5,'0',STR_PAD_LEFT);}
        else {$customer=trim((string)($_POST['customer']??''));$detail='Sale recorded: '.$quantity.' × '.$part['parts_name'].($customer!==''?' for '.$customer:'');}
        $statement=$link->prepare('UPDATE parts SET quantity=quantity-? WHERE parts_id=? AND quantity>=?');$statement->bind_param('iii',$quantity,$id,$quantity);$statement->execute();if($statement->affected_rows!==1)throw new RuntimeException('Stock changed while you were working. Refresh and retry.');$person=(string)$user['name'];$role=(string)$user['role'];$reference=(string)$part['sku'];$statement=$link->prepare('INSERT INTO activity_log(user_name,role,action,reference) VALUES(?,?,?,?)');$statement->bind_param('ssss',$person,$role,$detail,$reference);$statement->execute();$link->commit();inv_flash('success',$pageRole==='technician'?'Part usage recorded.':'Sale recorded and stock updated.');
    } catch(Throwable $error) { try{$link->rollback();}catch(Throwable $ignored){}$message=$error instanceof mysqli_sql_exception?($error->getCode()===1062?'That SKU already exists.':'Database could not save the change. Check that the prism database is writable and the linked records are valid.'):$error->getMessage();inv_flash('error',$message); }
    inv_go();
}

$search=trim((string)($_GET['q']??''));$edit=null;
if($pageRole==='admin'&&isset($_GET['edit'])){$id=(int)$_GET['edit'];$statement=$link->prepare('SELECT parts_id,sku,parts_name,parts_brand,parts_category,parts_compatible_device,quantity,minimum_stock,parts_price,parts_status FROM parts WHERE parts_id=?');$statement->bind_param('i',$id);$statement->execute();$edit=$statement->get_result()->fetch_assoc();}
$restockPart=null;if($pageRole==='admin'&&isset($_GET['restock'])){$id=(int)$_GET['restock'];$statement=$link->prepare('SELECT parts_id,sku,parts_name,quantity FROM parts WHERE parts_id=?');$statement->bind_param('i',$id);$statement->execute();$restockPart=$statement->get_result()->fetch_assoc();}
$sql='SELECT parts_id,sku,parts_name,parts_brand,parts_category,parts_compatible_device,quantity,minimum_stock,parts_price,parts_status FROM parts';if($search!=='')$sql.=($pageRole==='admin'?' WHERE ':' AND ').'(sku LIKE ? OR parts_name LIKE ? OR parts_brand LIKE ? OR parts_category LIKE ? OR parts_compatible_device LIKE ?)';$sql.=' ORDER BY parts_name';$statement=$link->prepare($sql);if($search!==''){$like='%'.$search.'%';$statement->bind_param('sssss',$like,$like,$like,$like,$like);}$statement->execute();$parts=$statement->get_result();$stats=$link->query('SELECT COUNT(*) total,COALESCE(SUM(quantity>0 AND quantity<=minimum_stock),0) low,COALESCE(SUM(quantity=0),0) out_count,COALESCE(SUM(quantity*parts_price),0) value FROM parts')->fetch_assoc();$repairs=[];
if($pageRole==='technician'){$userId=(int)$user['id'];$statement=$link->prepare("SELECT repair_id,customer_name,phone_model FROM repairs WHERE user_id=? AND LOWER(repair_status) NOT IN ('completed','collected','cancelled') ORDER BY repairs_created_at DESC");$statement->bind_param('i',$userId);$statement->execute();$repairs=$statement->get_result()->fetch_all(MYSQLI_ASSOC);}
$deviceOptions=[];$deviceQuery=$link->query("SELECT DISTINCT parts_compatible_device FROM parts WHERE parts_compatible_device IS NOT NULL AND parts_compatible_device<>'' ORDER BY parts_compatible_device");foreach($deviceQuery->fetch_all(MYSQLI_ASSOC) as $deviceRow){foreach(explode(',',(string)$deviceRow['parts_compatible_device']) as $deviceName){$deviceName=trim($deviceName);if($deviceName!=='')$deviceOptions[$deviceName]=$deviceName;}}$deviceOptions=array_values($deviceOptions);sort($deviceOptions,SORT_NATURAL|SORT_FLAG_CASE);$deviceValues=$edit?array_values(array_filter(array_map('trim',explode(',',(string)$edit['parts_compatible_device'])))):[''];if(!$deviceValues)$deviceValues=[''];$flash=$_SESSION['inv_flash']??null;unset($_SESSION['inv_flash']);$label=$pageRole==='admin'?'Inventory control':($pageRole==='technician'?'Parts for repairs':'Product availability');$initials=strtoupper(substr((string)$user['name'],0,1));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=inv_h($label)?> · PRISM</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Mono:wght@700&display=swap" rel="stylesheet"><link rel="stylesheet" href="../../css/prism.css?v=inventory-modal-2"><style>.inv-modal-backdrop{position:fixed!important;inset:0!important;z-index:99999!important;display:grid!important;place-items:center!important;padding:24px!important;background:rgba(15,22,39,.65)!important;backdrop-filter:blur(4px)}.inv-modal{position:relative!important;width:min(900px,100%)!important;max-height:90vh!important;overflow:auto!important;margin:0!important;background:#fff!important;border-radius:15px!important;box-shadow:0 24px 80px #10182b66!important}.device-row{display:flex;gap:7px;margin-bottom:7px}.device-row .input{flex:1;min-width:0}.device-remove{width:34px;height:38px;border:1px solid #e5e7ee;border-radius:8px;background:#fff;color:#7e8799;font-size:20px;cursor:pointer}.inventory-actions{display:flex;align-items:center;gap:6px;min-width:210px}.inventory-actions select{min-width:125px}.inventory-actions input[type=number]{width:72px}.inventory-actions input[type=text]{width:145px}.inventory-actions form{display:flex;align-items:center;gap:6px}.inventory-table td{vertical-align:middle}.role-note{color:#c4cbe0;font-size:12px}.mini-label{display:block;color:#9099aa;font-size:9px;margin-top:3px}.quick-links{display:flex;gap:9px;flex-wrap:wrap}.quick-links a{padding:12px 14px;border:1px solid #edf0f4;border-radius:9px;font-size:12px;font-weight:600;color:#565f76}@media(max-width:700px){.inventory-actions{min-width:190px}}</style></head><body><div class="shell"><aside class="side"><a class="brand" href="#"><span class="mark">P</span><span>PRISM</span></a><div class="workspace"><span>WORKSPACE</span><b><?=inv_h($user['role'])?></b></div><nav class="nav-list"><a class="nav" href