<?php if($flash):?><div class="flash <?=inv_h($flash[0])?>"><?=inv_h($flash[1])?></div><?php endif?><div class="welcome"><div><span class="promo-tag"><?=strtoupper(inv_h($pageRole))?> WORKSPACE</span><h2><?=$pageRole==='admin'?'Know what is on every shelf.':($pageRole==='technician'?'Find the right part for the repair.':'Check availability before promising it.')?></h2><p class="role-note"><?=$pageRole==='admin'?'Manage the catalogue, prices, and stock levels.':($pageRole==='technician'?'Look up active parts and record usage for your open repair jobs.':'Check active products and record customer sales.')?></p></div><?php if($pageRole==='admin'):?><a class="btn primary" href="?action=new">＋ Add inventory part</a><?php endif?></div><section class="stats"><article class="stat-card violet"><span class="stat-icon">▦</span><span>Parts tracked</span><strong><?=number_format((int)$stats['total'])?></strong><small>Items in catalogue</small></article><article class="stat-card amber"><span class="stat-icon">!</span><span>Low stock</span><strong><?=number_format((int)$stats['low'])?></strong><small>At or below minimum</small></article><article class="stat-card teal"><span class="stat-icon">○</span><span>Out of stock</span><strong><?=number_format((int)$stats['out_count'])?></strong><small>Need restocking</small></article><?php if($pageRole==='admin'):?><article class="stat-card blue"><span class="stat-icon">RM</span><span>Stock value</span><strong>RM <?=number_format((float)$stats['value'],2)?></strong><small>Current sell price value</small></article><?php endif?></section>
<?php if($pageRole==='admin'&&$restockPart):?><div class="inv-modal-backdrop" id="restockModal" role="dialog" aria-modal="true" aria-labelledby="restockTitle"><section class="card form-card inv-modal restock-modal"><div class="section-head"><div><span class="eyebrow">RESTOCK PART</span><h2 id="restockTitle">Add stock quantity</h2><p class="muted"><?=inv_h($restockPart['parts_name'])?> · <?=inv_h($restockPart['sku'])?> · Current stock: <?=inv_h($restockPart['quantity'])?></p></div><a class="close-link" href="<?=inv_h(basename(__FILE__))?>" aria-label="Close">×</a></div><form class="stack restock-form" method="post"><input type="hidden" name="csrf" value="<?=inv_h(inv_csrf())?>"><input type="hidden" name="action" value="restock"><input type="hidden" name="id" value="<?=inv_h($restockPart['parts_id'])?>"><label>Quantity to add<input class="input" type="number" name="quantity" min="1" step="1" value="1" required autofocus></label><div class="form-actions"><a class="btn ghost" href="<?=inv_h(basename(__FILE__))?>">Cancel</a><button class="btn primary">＋ Add stock</button></div></form></section></div><script>document.body.classList.add("modal-open");document.getElementById("restockModal")?.addEventListener("click",event=>{if(event.target.id==="restockModal")location.href="<?=inv_h(basename(__FILE__))?>";});document.addEventListener("keydown",event=>{if(event.key==="Escape")location.href="<?=inv_h(basename(__FILE__))?>";});</script><?php endif?><?php if($pageRole==='admin'&&(isset($_GET['action'])||$edit)):?><div class="inv-modal-backdrop" id="inventoryModal" role="dialog" aria-modal="true" aria-labelledby="inventoryModalTitle"><section class="card form-card inv-modal"><div class="section-head"><div><span class="eyebrow"><?=$edit?'EDIT PART':'NEW PART'?></span><h2 id="inventoryModalTitle"><?=$edit?'Update inventory details':'Add a part to inventory'?></h2></div><a class="close-link" href="<?=inv_h(basename(__FILE__))?>" aria-label="Close">×</a></div><form class="grid-form" method="post"><input type="hidden" name="csrf" value="<?=inv_h(inv_csrf())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id" value="<?=inv_h($edit['parts_id']??'')?>"><label>SKU<input class="input" name="sku" value="<?=inv_h($edit['sku']??'')?>" required></label><label>Part name<input class="input" name="name" value="<?=inv_h($edit['parts_name']??'')?>" required></label><?php $categoryOptions=['Parts','Screen','Battery','Charging','Camera','Speaker','Accessory','Consumables','Tools'];$savedCategory=(string)($edit['parts_category']??'Parts');$knownCategory=in_array($savedCategory,$categoryOptions,true); ?><label>Category<select class="input" name="category" id="categorySelect" required><option value="">Select category</option><?php foreach($categoryOptions as $option):?><option value="<?=inv_h($option)?>" <?=$knownCategory&&$savedCategory===$option?'selected':''?>><?=inv_h($option)?></option><?php endforeach?><option value="Other" <?=!$knownCategory?'selected':''?>>Other</option></select></label><label id="otherCategoryWrap" style="<?=$knownCategory?'display:none':''?>">Other category<input class="input" id="otherCategoryInput" name="category_other" value="<?=!$knownCategory?inv_h($savedCategory):''?>" <?=!$knownCategory?'required':''?> placeholder="Enter category"></label><label>Brand<input class="input" name="brand" value="<?=inv_h($edit['parts_brand']??'')?>"></label><div class="device-field"><span class="field-label">Compatible devices</span><div id="deviceFields"><?php foreach($deviceValues as $deviceValue):?><div class="device-row"><input class="input" name="devices[]" list="compatibleDeviceOptions" value="<?=inv_h($deviceValue)?>" placeholder="Choose or enter a device"><button class="device-remove" type="button" aria-label="Remove device field">−</button></div><?php endforeach?></div><button class="btn ghost sm" type="button" id="addDeviceButton">＋ Add device</button><small class="field-hint">Choose a suggestion or type a compatible device model.</small><datalist id="compatibleDeviceOptions"><?php foreach($deviceOptions as $deviceOption):?><option value="<?=inv_h($deviceOption)?>"><?php endforeach?></datalist></div><label>Price (RM)<input class="input" type="number" step=".01" min="0" name="price" value="<?=inv_h($edit['parts_price']??'0.00')?>"></label><label>Quantity<input class="input" type="number" min="0" name="quantity" value="<?=inv_h($edit['quantity']??0)?>"></label><label>Minimum stock<input class="input" type="number" min="0" name="minimum_stock" value="<?=inv_h($edit['minimum_stock']??5)?>"></label><div class="form-actions"><a class="btn ghost" href="<?=inv_h(basename(__FILE__))?>">Cancel</a><button class="btn primary">Save part →</button></div></form></section></div><script>const catSelect=document.getElementById("categorySelect"),otherWrap=document.getElementById("otherCategoryWrap"),otherInput=document.getElementById("otherCategoryInput"),deviceFields=document.getElementById("deviceFields");if(catSelect){const syncCategory=()=>{const isOther=catSelect.value==="Other";otherWrap.style.display=isOther?"":"none";otherInput.required=isOther;};catSelect.addEventListener("change",syncCategory);syncCategory();}document.body.classList.add("modal-open");document.getElementById("addDeviceButton")?.addEventListener("click",()=>{const row=document.createElement("div");row.className="device-row";row.innerHTML='<input class="input" name="devices[]" list="compatibleDeviceOptions" placeholder="Choose or enter a device"><button class="device-remove" type="button" aria-label="Remove device field">−</button>';deviceFields.appendChild(row);row.querySelector("input").focus();});deviceFields?.addEventListener("click",event=>{const button=event.target.closest(".device-remove");if(!button)return;const row=button.closest(".device-row");if(deviceFields.children.length>1)row.remove();else row.querySelector("input").value="";});document.getElementById("inventoryModal")?.addEventListener("click",event=>{if(event.target.id==="inventoryModal")location.href="<?=inv_h(basename(__FILE__))?>";});document.addEventListener("keydown",event=>{if(event.key==="Escape")location.href="<?=inv_h(basename(__FILE__))?>";});</script><?php endif?><section class="card table-card"><form class="search" method="get"><span>⌕</span><input name="q" value="<?=inv_h($search)?>" placeholder="Search part, SKU, brand, device, or category"><button class="btn ghost sm">Search</button><?php if($search!==''):?><a class="text-link" href="<?=inv_h(basename(__FILE__))?>">Clear</a><?php endif?></form><div class="table-wrap"><table class="inventory-table"><thead><tr><?php if($pageRole==='admin'):?><th>SKU</th><th>Part</th><th>Category</th><th>Brand</th><th>Compatible device</th><th>Qty</th><th>Minimum</th><th>Price</th><th>Status</th><th>Actions</th><?php elseif($pageRole==='technician'):?><th>SKU</th><th>Part</th><th>Device compatibility</th><th>Category</th><th>Available</th><th>Use on repair</th><?php else:?><th>SKU</th><th>Product</th><th>Category</th><th>Brand</th><th>Availability</th><th>Price</th><th>Record sale</th><?php endif?></tr></thead><tbody><?php if(!$parts->num_rows):?><tr><td colspan="10" class="empty-row">No matching parts found.</td></tr><?php else:while($part=$parts->fetch_assoc()):$low=(int)$part['quantity']<=(int)$part['minimum_stock'];[$stockLabel,$stockClass]=inv_stock_state((int)$part['quantity'],(int)$part['minimum_stock']);?><tr><td><span class="mono"><?=inv_h($part['sku'])?></span></td><td><b><?=inv_h($part['parts_name'])?></b><?php if($pageRole==='salesperson'):?><small class="mini-label"><?=inv_h($part['parts_compatible_device'])?></small><?php endif?></td><?php if($pageRole==='admin'):?><td><?=inv_h($part['parts_category'])?></td><td><?=inv_h($part['parts_brand'])?></td><td><?=inv_h($part['parts_compatible_device'])?></td><td><span class="stock <?=$low?'low':''?>"><?=inv_h($part['quantity'])?></span></td><td><?=inv_h($part['minimum_stock'])?></td><td>RM <?=number_format((float)$part['parts_price'],2)?></td><td><span class="pill <?=inv_h($stockClass)?>"><?=inv_h($stockLabel)?></span></td><td><div class="row-actions"><a class="icon-btn" title="Edit part" aria-label="Edit part" href="?edit=<?=$part['parts_id']?>"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L8 18l-4 1 1-4Z"/></svg></a><a class="icon-btn restock" title="Add stock quantity" aria-label="Add stock quantity" href="?restock=<?=$part['parts_id']?>"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg></a><form method="post" onsubmit="return confirm('Delete this part?')"><input type="hidden" name="csrf" value="<?=inv_h(inv_csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$part['parts_id']?>"><button class="icon-btn delete" title="Delete part" aria-label="Delete part"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2m3 0-.9 14H5.9L5 6m4 4v6m6-6v6"/></svg></button></form></div></td><?php elseif($pageRole==='technician'):?><td><?=inv_h($part['parts_compatible_device'])?></td><td><?=inv_h($part['parts_category'])?></td><td><span class="pill <?=inv_h($stockClass)?>"><?=inv_h($stockLabel)?></span><small class="mini-label">Qty: <?=inv_h($part['quantity'])?></small></td><td><form method="post" class="inventory-actions"><input type="hidden" name="csrf" value="<?=inv_h(inv_csrf())?>"><input type="hidden" name="action" value="use_part"><input type="hidden" name="part_id" value="<?=$part['parts_id']?>"><select class="input" name="repair_id" required><option value="">Assigned repair</option><?php foreach($repairs as $repair):?><option value="<?=$repair['repair_id']?>">RJ-<?=str_pad((string)$repair['repair_id'],5,'0',STR_PAD_LEFT)?> · <?=inv_h($repair['customer_name'])?></option><?php endforeach?></select><input class="input" type="number" name="quantity" min="1" max="<?=max(1,(int)$part['quantity'])?>" value="1" required><button class="btn primary sm" <?=((int)$part['quantity']<1||!$repairs)?'disabled':''?>>Use</button></form></td><?php else:?><td><?=inv_h($part['parts_category'])?></td><td><?=inv_h($part['parts_brand'])?></td><td><span class="pill <?=inv_h($stockClass)?>"><?=inv_h($stockLabel)?></span><small class="mini-label">Available: <?=inv_h($part['quantity'])?></small></td><td><b>RM <?=number_format((float)$part['parts_price'],2)?></b></td><td><form method="post" class="inventory-actions"><input type="hidden" name="csrf" value="<?=inv_h(inv_csrf())?>"><input type="hidden" name="action" value="record_sale"><input type="hidden" name="part_id" value="<?=$part['parts_id']?>"><input class="input" type="text" name="customer" placeholder="Customer (optional)"><input class="input" type="number" name="quantity" min="1" max="<?=max(1,(int)$part['quantity'])?>" value="1" required><button class="btn primary sm" <?=((int)$part['quantity']<1)?'disabled':''?>>Record sale</button></form></td><?php endif?></tr><?php endwhile;endif?></tbody></table></div></section></main></div></body></html>
